40	TEST_CASE("IcountTrigger: standalone lookup is silent until target hit")
41	{
42	  hybrid::IcountTrigger trig(/*target=*/100);
43	  CHECK_FALSE(trig.empty());
44	
45	  for (int i = 0; i < 99; ++i) {
46	    trig.observe_commit();
47	    CHECK_FALSE(trig.lookup(0xCAFE).has_value());
48	  }
49	
50	  trig.observe_commit();
51	  const auto hit = trig.lookup(0xCAFE);
52	  REQUIRE(hit);
53	  CHECK(hit->kind == HYBRID_HANDOFF_EXIT);
54	  CHECK(hit->insn == 0u);  // icount mode: insn is unused, sentinel zero
55	}
