78	TEST_CASE("HandoffController<IcountTrigger>: drains at exactly the Nth retire")
79	{
80	  RecordingBus bus;
81	  prime_drainable_bus(bus, /*dpc=*/0x80000400);
82	
83	  hybrid::IcountTrigger trigger(/*target=*/100);
84	  hybrid::HandoffController h(std::move(trigger), bus);
85	
86	  // 99 retires must not fire
87	  for (int i = 0; i < 99; ++i) {
88	    const auto state =
89	      h.on_retire(0x80000000);
90	    CHECK_FALSE(state.has_value());
91	  }
92	  // 100th retire fires the drain
93	  const auto state =
94	    h.on_retire(0x80000000);
95	  REQUIRE(state);
96	  CHECK(state->magic == HYBRID_STATE_MAGIC);
97	  CHECK(state->pc == 0x80000400);
98	}
