130	// Oracle exit-drain mode (verify_oracle F1): when exit_marker_mode or
131	// exit_pc_mode is set (plugin args `exit_marker=1` / `exit_pc=0x...`), a
132	// pure-QEMU run produces the differential verifier's reference state. Every
133	// insn gets an exec callback (icount-mode cost class): the tick ARMS on the
134	// ROI exit boundary (EXIT marker match, or vaddr == exit_pc) and DRAINS on
135	// the next callback. Exec callbacks fire before their insn executes, so the
136	// armed drain captures "after the boundary insn retired" -- exactly vsim's
137	// exit-drain record (DPC = next insn to execute) -- and reports that next
138	// insn's vaddr as pc, correct even when the boundary insn branches.
139	// Exclusive with the other trigger modes: the oracle run never hands off.
140	//
141	// drain_pc=0x... (optional modifier): drain at the first post-arm tick whose
142	// vaddr equals drain_pc, instead of the very next tick. The differential
143	// harness passes vsim's actual drained pc here: vsim's DMI halt lands a
144	// variable 0-3 insns past the trigger (the core keeps retiring while the
145	// haltreq propagates), and the two states only compare equal when both
146	// sides sample the SAME architectural point. If vsim's pc is never reached
147	// (a real control-flow divergence), the oracle never drains and QEMU runs
148	// to completion -- the caller sees exit != 200.
149	static uint64_t exit_pc_arg;
150	static int      exit_pc_mode;
151	static int      exit_marker_mode;
152	static uint64_t drain_pc_arg;
153	static int      drain_pc_set;
154	static volatile int oracle_armed;
155	
156	// Cosim oracle mode (cosim_roi F3): when cosim_marker_mode or cosim_pc_mode
157	// is set (plugin args `cosim_marker=1` / `cosim_pc=0x...`), a per-insn exec
158	// callback ARMS at the ROI entry boundary, then drains hybrid_state_v1 at
159	// the post-entry retire counts listed in cosim_counts=a:b:c (strictly
160	// ascending). Every count but the last writes <outfile>.ckpt<k> (k from 1)
161	// and execution continues; the LAST drains <outfile> and exits 200. The
162	// counts come from the vsim leg's checkpoint minstret deltas, so both
163	// engines sample the SAME architectural points (see docs/archive/cosim_roi.md).
164	//
165	// Counting mirrors the vsim leg's minstret reference point:
166	//   marker mode: the ENTER marker is counted by NEITHER side (QEMU1 drains
167	//     pre-marker, vsim resumes past it) -- the arming tick does not count.
168	//   pc mode: the boundary insn retires INSIDE the window (the pc-mode
169	//     handoff resumes AT the boundary), so the arming tick counts it.
170	// Exclusive with every other trigger mode (including the exit oracle).
171	static uint64_t *cosim_counts;
172	static size_t    cosim_n_counts;
173	static uint64_t  cosim_pc_arg;
174	static int       cosim_pc_mode;
175	static int       cosim_marker_mode;
176	static volatile int cosim_armed;
177	static uint64_t  cosim_done;   // post-entry retires so far
178	static size_t    cosim_idx;    // next cosim_counts[] target
179	
180	// Lock-step oracle mode (cosim_redesign F5): `lockstep_pc=0x...` arms at
181	// the given vaddr, then drains the full state BEFORE every execution
182	// attempt, appending each record to the `outfile` stream (outfile IS the
183	// stream in this mode; there is no separate final state file). Exec
184	// callbacks fire pre-execution, so record k = state before attempt k+1 --
185	// the exact point where vsim's dcsr.step halt lands, traps included (a
186	// trapped attempt's next callback is the handler entry on both sides).
187	// Stops at `lockstep_max=K` records (exit 200) or at natural program exit.
188	static uint64_t  lockstep_pc_arg;
189	static int       lockstep_pc_mode;
190	static uint64_t  lockstep_max;
191	static volatile int lockstep_armed;
192	static uint64_t  lockstep_count;
