273	// Reads up to `dst_max` bytes from a register handle. Returns the byte
274	// count written (0 on failure or NULL handle). Used for vector regs whose
275	// width = vlenb bytes.
276	static size_t read_reg_bytes(struct qemu_plugin_register *h,
277	                             uint8_t *dst, size_t dst_max)
278	{
279	    if (!h || dst_max == 0) return 0;
280	    g_autoptr(GByteArray) buf = g_byte_array_new();
281	    int sz = qemu_plugin_read_register(h, buf);
282	    if (sz <= 0) return 0;
283	    size_t n = (size_t) sz < dst_max ? (size_t) sz : dst_max;
284	    memcpy(dst, buf->data, n);
285	    return n;
286	}
