108	Cli parse_cli(int argc, char** argv) {
109	  std::vector<std::string> args;
110	  args.reserve(argc > 1 ? static_cast<size_t>(argc - 1) : 0);
111	  for (int i = 1; i < argc; ++i) args.emplace_back(argv[i]);
112	  return parse_cli(args);
113	}
