24	struct CsrTriggerHit
25	{
26	  hybrid_handoff_kind kind;
27	  uint32_t insn;
28	};
29	
30	class CsrTrigger
31	{
32	public:
33	  void scan_buffer(std::span<const uint8_t> code, uint64_t base_pc)
34	  {
35	    std::size_t i = 0;
36	    while (i + sizeof(uint16_t) <= code.size()) {
37	      uint16_t lo = 0;
38	      std::memcpy(&lo, code.data() + i, sizeof(lo));
39	
40	      const bool is_32 = (lo & 0x3u) == 0x3u;
41	      if (is_32) {
42	        if (i + sizeof(uint32_t) > code.size()) break;
43	        uint32_t insn = 0;
44	        std::memcpy(&insn, code.data() + i, sizeof(insn));
45	        hybrid_handoff_kind kind = HYBRID_HANDOFF_NONE;
46	        if (hybrid_match_handoff_insn(insn, &kind)) {
47	          hits_.insert_or_assign(base_pc + i, CsrTriggerHit{kind, insn});
48	        }
49	        i += sizeof(uint32_t);
50	      } else {
51	        i += sizeof(uint16_t);
52	      }
53	    }
54	  }
55	
56	  // PC-trigger mode: insert a synthetic hit without scanning. Used when the
57	  // orchestrator passes --hybrid-exit-pc on the CLI; in that case the binary
58	  // need not contain a marker HINT, and `insn` is unused (HandoffController
59	  // dispatches on `kind` alone; PC mode only inserts EXIT).
60	  void add_pc_hit(uint64_t pc, hybrid_handoff_kind kind)
61	  {
62	    hits_.insert_or_assign(pc, CsrTriggerHit{kind, /*insn=*/0u});
63	  }
64	
65	  auto lookup(uint64_t pc) const -> std::optional<CsrTriggerHit>
66	  {
67	    if (auto it = hits_.find(pc); it != hits_.end()) return it->second;
68	    return std::nullopt;
69	  }
70	
71	  auto empty() const -> bool { return hits_.empty(); }
72	
73	  // Collect every recorded PC whose hit matches `kind`. The result is sorted
74	  // ascending so callers (e.g. the ROI kanata-gate derivation) get a stable
75	  // order regardless of hash-map iteration order.
76	  auto pcs_of_kind(hybrid_handoff_kind kind) const -> std::vector<uint64_t>
77	  {
78	    std::vector<uint64_t> pcs;
79	    pcs.reserve(hits_.size());
80	    for (const auto& [pc, hit]: hits_)
81	      if (hit.kind == kind) pcs.push_back(pc);
82	    std::sort(pcs.begin(), pcs.end());
83	    return pcs;
84	  }
85	
86	private:
87	  std::unordered_map<uint64_t, CsrTriggerHit> hits_;
88	};
