250	  // run -- callers pass exactly one form.
251	  void enable_hybrid_handoff(const std::string& elf_path,
252	                             const std::string& state_out_path,
253	                             std::optional<uint64_t> exit_pc = std::nullopt,
254	                             uint64_t vsim_warmup_icount = 0)
255	  {
256	    hybrid::CsrTrigger trigger;
257	    if (exit_pc) {
258	      trigger.add_pc_hit(*exit_pc, HYBRID_HANDOFF_EXIT);
259	      spdlog::info("hybrid: PC-trigger mode, exit_pc=0x{:x}", *exit_pc);
260	    } else {
261	      auto elf = LIEF::ELF::Parser::parse(elf_path);
262	      if (!elf)
263	        throw std::runtime_error(
264	          "enable_hybrid_handoff: failed to parse " + elf_path);
265	      for (const auto& seg: elf->segments()) {
266	        if (seg.type() != LIEF::ELF::SEGMENT_TYPES::PT_LOAD) continue;
267	        if ((static_cast<unsigned>(seg.flags()) & 1u) == 0u) continue;  // PF_X
268	        const auto content = seg.content();
269	        const std::span<const uint8_t> bytes{content.data(), content.size()};
270	        trigger.scan_buffer(bytes, seg.virtual_address());
271	      }
272	    }
273	
274	    auto snapshot = make_handoff_snapshot(vsim_warmup_icount);
275	    hybrid_handoff_.emplace(std::move(trigger), *hybrid_dmi_bus_,
276	                            std::move(snapshot), v_scratch_gpa());
277	    if (hybrid_input_state_)
278	      hybrid_handoff_->set_passthrough_input(*hybrid_input_state_);
279	    hybrid_state_path_ = state_out_path;
280	  }
