301	  // cosim_roi F2 / cosim_redesign F3: drain resumable checkpoints -- every
302	  // `interval` retires, or at each explicit retire target (the last target
303	  // finishes the run). Records append to the `<handoff_out>.ckpts` stream
304	  // (concatenated hybrid_state_v1; count = filesize / sizeof). Call AFTER
305	  // enable_hybrid_handoff -- checkpoints ride the CSR/PC handoff
306	  // controller, so icount mode cannot carry them.
307	  void enable_hybrid_cosim(uint64_t interval)
308	  {
309	    spdlog::info("hybrid cosim: checkpoint every {} retires", interval);
310	    require_handoff_for_cosim();
311	    hybrid_handoff_->enable_cosim(interval, make_cosim_stream_sink());
