345	  // L26: the GUEST address of the V-register transport page -- the top page of
346	  // the mapped RAM span. The driver maps one page above --mem-size (scheme D),
347	  // so this sits just past the program's declared RAM and never collides with
348	  // its data/stack. Single source of truth handed to ResumeDriver/StateDrain.
349	  auto v_scratch_gpa() const -> uint64_t
